22	/**
23	 * Parses a CSS selector into an Evaluator tree.
24	 */
25	public class QueryParser implements AutoCloseable {
26	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
27	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
28	    private final static char[] SequenceEnders = {',', ')'};
29	
30	    private final TokenQueue tq;
31	    private final String query;
32	    private boolean inNodeContext; // ::comment:contains should act on node value, vs element text
33	    private int relativeDepth; // >0 while parsing the relative selector list inside a :has()
34	
35	    /**
36	     * Create a new QueryParser.
37	     * @param query CSS query
38	     */
39	    private QueryParser(String query) {
40	        Validate.notEmpty(query);
41	        query = query.trim();
42	        this.query = query;
43	        this.tq = new TokenQueue(query);
44	    }
45	
46	    /**
47	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
48	     parse it once and reuse the Evaluator.
49	
50	     @param query CSS query
51	     @return Evaluator
52	     @see Selector selector query syntax
53	     @throws Selector.SelectorParseException if the CSS query is invalid
54	     */
55	    public static Evaluator parse(String query) {
56	        try (QueryParser p = new QueryParser(query)) {
57	            return p.parse();
58	        } catch (IllegalArgumentException e) {
59	            throw new Selector.SelectorParseException(e.getMessage());
60	        }
61	    }
62	
63	    /**
64	     Parse the query. We use this simplified expression of the grammar:
65	     <pre>
66	     SelectorGroup   ::= Selector (',' Selector)*
67	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
68	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
69	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
70	     Combinator      ::= S+         // descendant (whitespace)
71	     | '>'       // child
72	     | '+'       // adjacent sibling
73	     | '~'       // general sibling
74	     </pre>
75	
76	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
77	     */
78	    Evaluator parse() {
79	        Evaluator eval = parseSelectorGroup();
80	        tq.consumeWhitespace();
81	        if (!tq.isEmpty())
82	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
83	        return eval;
84	    }
85	
86	    Evaluator parseSelectorGroup() {
87	        // SelectorGroup. Into an Or if > 1 Selector
88	        Evaluator left = parseSelector();
89	        while (tq.matchChomp(',')) {
90	            Evaluator right = parseSelector();
91	            left = or(left, right);
92	        }
93	        return left;
94	    }
95	
96	    Evaluator parseSelector() {
97	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
98	        tq.consumeWhitespace();
99	
100	        Evaluator left;
101	        boolean relativeBare = false; // true for a bare branch of a :has() relative list (no leading combinator / :scope)
102	        if (tq.matchesAny(Combinators)) {
103	            // e.g. query is "> div"; left side is root element
104	            left = new StructuralEvaluator.Root();
105	        } else {
106	            left = parseSimpleSequence();
107	            if (relativeDepth > 0 && !containsScope(left))
108	                relativeBare = true; // the leftmost step may not land on the scope element itself
109	        }
110	
111	        boolean firstCombinator = true;
112	        while (true) {
113	            char combinator = 0;
114	            if (tq.consumeWhitespace())
115	                combinator = ' ';            // maybe descendant?
116	            if (tq.matchesAny(Combinators)) // no, explicit
117	                combinator = tq.consume();
118	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
119	                break;
120	
121	            if (combinator != 0) {
122	                Evaluator right = parseSimpleSequence();
123	                left = combinator(left, combinator, right, relativeBare && firstCombinator);
124	                firstCombinator = false;
125	            } else {
126	                break;
127	            }
128	        }
129	        return left;
130	    }
131	
132	    Evaluator parseSimpleSequence() {
133	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
134	        Evaluator left = null;
135	        tq.consumeWhitespace();
136	
137	        // one optional type selector
138	        if (tq.matchesWord() || tq.matches("*|"))
139	            left = byTag();
140	        else if (tq.matchChomp('*'))
141	            left = new Evaluator.AllElements();
142	
143	        // zero or more subclasses (#, ., [)
144	        while(true) {
145	            Evaluator right = parseSubclass();
146	            if (right != null) {
147	                left = and(left, right);
148	            }
149	            else break; // no more simple tokens
150	        }
151	
152	        if (left == null)
153	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
154	        return left;
155	    }
156	
157	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
158	        return combinator(left, combinator, right, false);
159	    }
160	
161	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right, boolean strictRoot) {
162	        switch (combinator) {
163	            case '>':
164	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
165	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
166	                run.add(right);
167	                if (strictRoot) run.strictRoot = true; // leftmost step may not land on the :has() scope
168	                return run;
169	            case ' ':
170	                StructuralEvaluator.Ancestor ancestor = new StructuralEvaluator.Ancestor(left);
171	                if (strictRoot) ancestor.strictRoot = true; // leftmost step may not land on the :has() scope
172	                return and(ancestor, right);
173	            case '+':
174	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
175	            case '~':
176	                return and(new StructuralEvaluator.PreviousSibling(left), right);
177	            default:
178	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
179	        }
180	    }
181	
182	    @Nullable Evaluator parseSubclass() {
183	        //  Subclass: ID | Class | Attribute | Pseudo
184	        if      (tq.matchChomp('#'))    return byId();
185	        else if (tq.matchChomp('.'))    return byClass();
186	        else if (tq.matches('['))       return byAttribute();
187	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
188	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
189	        else                            return null;
190	    }
191	
192	    /** Merge two evals into an Or. */
193	    static Evaluator or(Evaluator left, Evaluator right) {
194	        if (left instanceof CombiningEvaluator.Or) {
195	            ((CombiningEvaluator.Or) left).add(right);
196	            return left;
197	        }
198	        return new CombiningEvaluator.Or(left, right);
199	    }
200	
201	    /** Merge two evals into an And. */
202	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
203	        if (left == null) return right;
204	        if (left instanceof CombiningEvaluator.And) {
205	            ((CombiningEvaluator.And) left).add(right);
206	            return left;
207	        }
208	        return new CombiningEvaluator.And(left, right);
209	    }
