211	    private Evaluator parsePseudoSelector() {
212	        final String pseudo = tq.consumeCssIdentifier();
213	        switch (pseudo) {
214	            case "lt":
215	                return new Evaluator.IndexLessThan(consumeIndex());
216	            case "gt":
217	                return new Evaluator.IndexGreaterThan(consumeIndex());
218	            case "eq":
219	                return new Evaluator.IndexEquals(consumeIndex());
220	            case "has":
221	                return has();
222	            case "is":
223	                return is();
224	            case "contains":
225	                return contains(false);
226	            case "containsOwn":
227	                return contains(true);
228	            case "containsWholeText":
229	                return containsWholeText(false);
230	            case "containsWholeOwnText":
231	                return containsWholeText(true);
232	            case "containsData":
233	                return containsData();
234	            case "matches":
235	                return matches(false);
236	            case "matchesOwn":
237	                return matches(true);
238	            case "matchesWholeText":
239	                return matchesWholeText(false);
240	            case "matchesWholeOwnText":
241	                return matchesWholeText(true);
242	            case "not":
243	                return not();
244	            case "lang":
245	                return lang();
246	            case "nth-child":
247	                return cssNthChild(false, false);
248	            case "nth-last-child":
249	                return cssNthChild(true, false);
250	            case "nth-of-type":
251	                return cssNthChild(false, true);
252	            case "nth-last-of-type":
253	                return cssNthChild(true, true);
254	            case "first-child":
255	                return new Evaluator.IsFirstChild();
256	            case "last-child":
257	                return new Evaluator.IsLastChild();
258	            case "first-of-type":
259	                return new Evaluator.IsFirstOfType();
260	            case "last-of-type":
261	                return new Evaluator.IsLastOfType();
262	            case "only-child":
263	                return new Evaluator.IsOnlyChild();
264	            case "only-of-type":
265	                return new Evaluator.IsOnlyOfType();
266	            case "empty":
267	                return new Evaluator.IsEmpty();
268	            case "blank":
269	                return new NodeEvaluator.BlankValue();
270	            case "root":
271	                return new Evaluator.IsRoot();
272	            case "scope":
273	                return new StructuralEvaluator.Scope();
274	            case "matchText": {
275	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
276	                Evaluator.MatchText matchText = new Evaluator.MatchText();
277	                return matchText;
278	            }
279	            default:
280	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
281	        }
282	    }
283	
284	    // ::comment etc
285	    private Evaluator parseNodeSelector() {
286	        final String pseudo = tq.consumeCssIdentifier();
287	        inNodeContext = true;  // Enter node context
288	
289	        Evaluator left;
290	        switch (pseudo) {
291	            case "node":
292	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
293	                break;
294	            case "leafnode":
295	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
296	                break;
297	            case "text":
298	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
299	                break;
300	            case "comment":
301	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
302	                break;
303	            case "data":
304	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
305	                break;
306	            case "cdata":
307	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
308	                break;
309	            default:
310	                throw new Selector.SelectorParseException(
311	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
312	        }
313	
314	        // Handle following subclasses in node context (like ::comment:contains())
315	        Evaluator right;
316	        while ((right = parseSubclass()) != null) {
317	            left = and(left, right);
318	        }
319	
320	        inNodeContext = false;
321	        return left;
322	    }
323	
324	    private Evaluator byId() {
325	        String id = tq.consumeCssIdentifier();
326	        Validate.notEmpty(id);
327	        return new Evaluator.Id(id);
328	    }
329	
330	    private Evaluator byClass() {
331	        String className = tq.consumeCssIdentifier();
332	        Validate.notEmpty(className);
333	        return new Evaluator.Class(className.trim());
334	    }
335	
336	    private Evaluator byTag() {
337	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
338	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
339	        // consistency - both the selector and the element tag
340	        String tagName = normalize(tq.consumeElementSelector());
341	        Validate.notEmpty(tagName);
342	
343	        // namespaces:
344	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
345	            String plainTag = tagName.substring(2); // strip *|
346	            return new CombiningEvaluator.Or(
347	                new Evaluator.Tag(plainTag),
348	                new Evaluator.TagEndsWith(":" + plainTag)
349	            );
350	        } else if (tagName.endsWith("|*")) { // ns|*
351	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
352	            return new Evaluator.TagStartsWith(ns);
353	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
354	            tagName = tagName.replace("|", ":");
355	        }
356	
357	        return new Evaluator.Tag(tagName);
358	    }
359	
360	    private Evaluator byAttribute() {
361	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
362	            return evaluatorForAttribute(cq);
363	        }
364	    }
365	
366	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
367	        cq.consumeWhitespace();
368	        String key = consumeAttributeKey(cq);
369	        key = normalize(key);
370	        Validate.notEmpty(key);
371	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
372	        cq.consumeWhitespace();
373	        final Evaluator eval;
374	
375	        if (cq.isEmpty()) {
376	            if (key.startsWith("^"))
377	                eval = new Evaluator.AttributeStarting(key.substring(1));
378	            else if (key.equals("*")) // any attribute
379	                eval = new Evaluator.AttributeStarting("");
380	            else
381	                eval = new Evaluator.Attribute(key);
382	        } else if (cq.matchChomp("~=")) { // regex match; the remainder of the queue (less surrounding whitespace) is the pattern
383	            eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder().trim()));
384	        } else {
385	            final String op;
386	            if (cq.matchChomp("!=")) op = "!=";
387	            else if (cq.matchChomp("^=")) op = "^=";
388	            else if (cq.matchChomp("$=")) op = "$=";
389	            else if (cq.matchChomp("*=")) op = "*=";
390	            else if (cq.matchChomp("=")) op = "=";
391	            else throw new Selector.SelectorParseException(
392	                "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
393	
394	            cq.consumeWhitespace();
395	            final String rawValue = consumeAttributeValue(cq);
396	            final boolean quoted = !rawValue.isEmpty() && (rawValue.charAt(0) == '"' || rawValue.charAt(0) == '\'');
397	            // Quoted (CSS string) values keep their quotes and are decoded in the evaluator; bare values have their
398	            // CSS escapes decoded here, so escaped and unescaped forms of the same value match equally.
399	            final String value = quoted ? rawValue : TokenQueue.unescapeCss(rawValue);
400	            cq.consumeWhitespace();
401	
402	            // Quoted (CSS string) values compare case-sensitively by default; bare values keep jsoup's historical
403	            // case-insensitive compare. An 'i' or 's' modifier after the value overrides the default.
404	            boolean caseSensitive = quoted;
405	            if (!cq.isEmpty()) {
406	                String modifier = cq.consumeCssIdentifier();
407	                if (modifier.equalsIgnoreCase("s")) caseSensitive = true;
408	                else if (modifier.equalsIgnoreCase("i")) caseSensitive = false;
409	                else throw new Selector.SelectorParseException(
410	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, modifier + cq.remainder());
411	                cq.consumeWhitespace();
412	                if (!cq.isEmpty())
413	                    throw new Selector.SelectorParseException(
414	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
415	            }
416	
417	            switch (op) {
418	                case "=":
419	                    eval = new Evaluator.AttributeWithValue(key, value, caseSensitive);
420	                    break;
421	                case "!=":
422	                    eval = new Evaluator.AttributeWithValueNot(key, value, caseSensitive);
423	                    break;
424	                case "^=":
425	                    eval = new Evaluator.AttributeWithValueStarting(key, value, caseSensitive);
426	                    break;
427	                case "$=":
428	                    eval = new Evaluator.AttributeWithValueEnding(key, value, caseSensitive);
429	                    break;
430	                case "*=":
431	                    eval = new Evaluator.AttributeWithValueContaining(key, value, caseSensitive);
432	                    break;
433	                default:
434	                    throw new Selector.SelectorParseException(
435	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
436	            }
437	        }
438	        return eval;
439	    }
