        boolean inDouble = false;
        boolean prevEscaped = false;
        for (int i = 0; i < arg.length(); i++) {
            char c = arg.charAt(i);
            if (c == '\\' && i + 1 < arg.length()) {
                i++; // skip the escaped char
                prevEscaped = true;
                continue;
