                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
                && arg.regionMatches(true, i, "of", 0, 2)
                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
