252			// serialize + reparse, then run the same selector: equivalent elements, order and dedup
253			String css = ":nth-child(2 of b, i)";
254			Document doc = Jsoup.parse("<div><b>1</b><i>2</i><b>3</b><i>4</i><b>5</b></div>");
255			Document reparse = Jsoup.parse(doc.html());
256			assertEquals(doc.select(css).eachText(), reparse.select(css).eachText());
257			assertEquals("2", String.join(",", doc.select(css).eachText()));
258	
259			// consecutive calls on different documents do not share parsing or counting state
260			Document d1 = Jsoup.parse("<div><b>1</b><b>2</b></div>");
261			Document d2 = Jsoup.parse("<div><b>a</b><b>b</b><b>c</b></div>");
262			assertEquals("2", String.join(",", d1.select(":nth-child(2 of b)").eachText()));
263			assertEquals("b", String.join(",", d2.select(":nth-child(2 of b)").eachText()));
264			assertEquals("2", String.join(",", d1.select(":nth-child(2 of b)").eachText()));
265	
266			// a parsed evaluator reused across documents is likewise isolated
267			Evaluator eval = QueryParser.parse(":nth-child(2 of b)");
268			assertEquals("2", String.join(",", d1.select(eval).eachText()));
269			assertEquals("b", String.join(",", d2.select(eval).eachText()));
270			assertEquals("2", String.join(",", d1.select(eval).eachText()));
