272			// empty documents and no-match queries give an empty result rather than throwing
273			assertTrue(Jsoup.parse("").select(":nth-child(1 of b)").isEmpty());
274			assertTrue(Jsoup.parse("<p>x</p>").select(":nth-child(1 of b)").isEmpty());
