import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.jsoup.select.QueryParser;
import org.jsoup.select.Evaluator;

public class Probe {
    static int fails = 0;
    static void check(String label, Object actual, Object expected) {
        boolean ok = String.valueOf(actual).equals(String.valueOf(expected));
        if (!ok) { fails++; System.out.println("FAIL " + label + " => got [" + actual + "] expected [" + expected + "]"); }
        else System.out.println("ok   " + label + " = " + actual);
    }
    static String ids(Document d, String css) { return String.join(",", d.select(css).eachAttr("id")); }
    static String texts(Document d, String css) { return String.join(",", d.select(css).eachText()); }

    static void expectThrow(String label, String css) {
        try { Document d = Jsoup.parse("<div id=s><b id=x>1</b><i id=y>2</i><b id=z>3</b></div>");
            d.select(css);
            fails++; System.out.println("FAIL " + label + " expected throw for: " + css);
        } catch (Selector.SelectorParseException e) {
            System.out.println("ok   " + label + " threw: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        Document doc = Jsoup.parse(
            "<div id=s><b id=x>a</b><i id=y>b</i><b id=z>c</b><em>d</em><b id=w>e</b></div>");

        // basic of
        check("2 of b", ids(doc, "#s>:nth-child(2 of b)"), "z");
        check("last 1 of b,i", ids(doc, "#s>:nth-last-child(1 of b,i)"), "w");
        check("last 2 of b", ids(doc, "#s>:nth-last-child(2 of b)"), "z");
        check("odd of b", ids(doc, "#s>:nth-child(odd of b)"), "x,w");
        check("even of b", ids(doc, "#s>:nth-child(even of b)"), "z");
        check("-n+2 of b", ids(doc, "#s>:nth-child(-n+2 of b)"), "x,z");
        check("nth-last odd/even of b", ids(doc, "#s>:nth-last-child(even of b)"), "z");
        check("nth-last odd of b", ids(doc, "#s>:nth-last-child(odd of b)"), "x,w");

        // nth-last returns document order even when multiple matches across parents
        Document multi = Jsoup.parse(
            "<div><b id=a1>1</b><b id=a2>2</b><b id=a3>3</b></div>" +
            "<div><b id=b1>4</b><b id=b2>5</b><b id=b3>6</b></div>");
        check("last odd across parents doc order", ids(multi, ":nth-last-child(odd of b)"), "a1,a3,b1,b3");
        check("last 1 across parents doc order", ids(multi, ":nth-last-child(1 of b)"), "a3,b3");

        // zero step: 0n+1 only first
        check("0n+1 of b", ids(doc, "#s>:nth-child(0n+1 of b)"), "x");
        check("0n+2 of b", ids(doc, "#s>:nth-child(0n+2 of b)"), "z");
        check("0n+5 of b (out of range)", ids(doc, "#s>:nth-child(0n+5 of b)"), "");
        // negative starting points
        check("-5", ids(doc, "#s>:nth-child(-5 of b)"), "");
        check("0 of b", ids(doc, "#s>:nth-child(0 of b)"), "");

        // candidate self must match S
        check("global p tag + of i", ids(doc, "#s>*:nth-child(1 of i)"), "y");

        // duplicate branches counted once
        check("dup b,b,b", ids(doc, "#s>:nth-child(2 of b, b, b)"), "z");

        // quoted comma in attr
        Document q = Jsoup.parse("<div id=s><b id=x title='p,q'>1</b><i id=y>2</i><b id=z title='p,q'>3</b></div>");
        check("quoted comma", ids(q, "#s>:nth-child(2 of b[title='p,q'])"), "z");

        // escapes: class with escaped char
        Document e = Jsoup.parse("<div id=s><b id=x class='a,b'>1</b><b id=z class='a,b'>2</b><b id=w>3</b></div>");
        check("escaped comma in class", ids(e, "#s>:nth-child(2 of b.a\\,b)"), "z");

        // outer dedup + order
        Document d2 = Jsoup.parse("<div id=s><b id=x>1</b><i id=y>2</i><b id=z>3</b></div>");
        check("outer dedup order", ids(d2, "#s>:nth-child(odd of b), b, #s>*"), "x,y,z");

        // legal no-match branch does not kill others
        check("bad+good branch", ids(d2, "#s>:nth-child(9 of b), i"), "y");

        // ---- error cases ----
        expectThrow("empty of", ":nth-child(2 of )");
        expectThrow("missing An+B", ":nth-child(of b)");
        expectThrow("unclosed paren", ":nth-child(2 of b");
        expectThrow("unclosed quote in S", ":nth-child(2 of b[title='x])");
        expectThrow("bad escape", ":nth-child(2 of b[\\]]");
        expectThrow("combinator no rhs", ":nth-child(2 of b > )");
        expectThrow("garbage symbol", ":nth-child(2 of b ?? c)");
        expectThrow("of with nth-of-type", ":nth-of-type(2 of b)");
        expectThrow("bad formula", ":nth-child(abc of b)");
        expectThrow("empty S nested", ":nth-child(2 of b, )");
        expectThrow("extra content", ":nth-child(2 of b)c)");

        // after failure, normal queries still work
        Document fresh = Jsoup.parse("<div id=s><b id=x>1</b><i id=y>2</i><b id=z>3</b></div>");
        check("normal after failure (tag)", ids(fresh, "b"), "x,z");
        check("normal after failure (attr)", ids(fresh, "[id]"), "s,x,y,z");
        check("structural after failure", ids(fresh, "#s > i"), "y");
        check("plain nth after failure", ids(fresh, "#s > :nth-child(2)"), "y");

        // empty doc
        check("empty doc", Jsoup.parse("").select(":nth-child(1 of b)").size(), 0);

        // no mutation
        String before = doc.toString();
        doc.select(":nth-child(2 of b, i):nth-last-child(-n+2 of b)");
        check("no mutation", doc.toString().equals(before), true);

        // round trip
        Document rt = Jsoup.parse("<div><b>1</b><i>2</i><b>3</b><i>4</i><b>5</b></div>");
        Document rp = Jsoup.parse(rt.html());
        check("roundtrip texts eq", texts(rt, ":nth-child(2 of b, i)").equals(texts(rp, ":nth-child(2 of b, i)")), true);

        // reused evaluator isolation
        Evaluator ev = QueryParser.parse(":nth-child(2 of b)");
        Document dd1 = Jsoup.parse("<div><b>1</b><b>2</b></div>");
        Document dd2 = Jsoup.parse("<div><b>a</b><b>b</b><b>c</b></div>");
        check("iso d1", texts(dd1, css(ev)), "2");
        check("iso d2", texts(dd2, css(ev)), "b");
        check("iso d1 again", texts(dd1, css(ev)), "2");

        System.out.println(fails == 0 ? "ALL PASS" : (fails + " FAILURES"));
    }
    static String css(Evaluator ev){ return ev.toString(); }
}
