178	                } else if (c == open) {
179	                    depth++;
180	                    if (depth > 1) accum.append(c); // don't include the outer match pair in the return
181	                } else if (c == close) {
182	                    depth--;
183	                    if (depth > 0) accum.append(c);
184	                } else {
185	                    accum.append(c);
186	                }
187	            }
188	            prev = c;
189	        } while (depth > 0);
