229	     @see <a href="https://www.w3.org/TR/css-syntax-3/#consume-an-escaped-code-point">CSS Syntax Module Level 3, consume an escaped code point</a>
230	     */
231	    public void consumeCssEscapeSequence(StringBuilder out) {
232	        advance(); // drop the escape character
233	        if (isEmpty()) throw new IllegalArgumentException("Invalid escape sequence: \\ at end of input");
234	        consumeCssEscapeSequenceInto(out);
235	    }
236	
237	    /**
238	     Decodes CSS escape sequences in the input string: a backslash followed by a character yields that character, and a
239	     backslash followed by up to 6 hexadecimal digits (and one optional trailing whitespace) yields that code point.
240	     @param in the string to decode
241	     @return the decoded string
242	     @throws IllegalArgumentException if an escape sequence is incomplete (an escape character at the end of the input)
243	     */
244	    public static String unescapeCss(String in) {
245	        if (in.indexOf(Esc) == -1) return in;
246	
247	        StringBuilder out = StringUtil.borrowBuilder();
248	        TokenQueue q = new TokenQueue(in);
249	        while (!q.isEmpty()) {
250	            if (q.matches(Esc)) q.consumeCssEscapeSequence(out);
251	            else out.append(q.consume());
252	        }
253	        q.close();
254	        return StringUtil.releaseBuilder(out);
255	    }
256	
257	    /**
258	     Given a CSS identifier (such as a tag, ID, or class), escape any CSS special characters that would otherwise not be
259	     valid in a selector.
260	
261	     @see <a href="https://www.w3.org/TR/cssom-1/#serialize-an-identifier">CSS Object Model, serialize an identifier</a>
262	     */
263	    public static String escapeCssIdentifier(String in) {
264	        if (in.isEmpty()) return in;
265	
266	        StringBuilder out = StringUtil.borrowBuilder();
267	        TokenQueue q = new TokenQueue(in);
268	
269	        char firstChar = q.current();
270	        if (firstChar == Hyphen_Minus) {
271	            q.advance();
272	            if (q.isEmpty()) {
273	                // If the character is the first character and is a "-" (U+002D), and there is no second character, then
274	                // the escaped character.
275	                appendEscaped(out, Hyphen_Minus);
276	            } else {
277	                out.append(Hyphen_Minus);
278	
279	                char secondChar = q.current();
280	                if (StringUtil.isDigit(secondChar)) {
281	                    // If the character is the second character and is in the range [0-9] (U+0030 to U+0039) and the
282	                    // first character is a "-" (U+002D), then the character escaped as code point.
283	                    appendEscapedCodepoint(out, q.consume());
284	                }
285	            }
286	        } else if (StringUtil.isDigit(firstChar)) {
287	            // If the character is the first character and is in the range [0-9] (U+0030 to U+0039), then the character
288	            // escaped as code point.
289	            appendEscapedCodepoint(out, q.consume());
290	        }
291	
292	        while (!q.isEmpty()) {
293	            // Note: It's fine to iterate on chars because non-ASCII characters are never escaped. So surrogate pairs
294	            // are kept intact.
295	            char c = q.consume();
296	            if (c == Unicode_Null) {
297	                // If the character is NULL (U+0000), then the REPLACEMENT CHARACTER (U+FFFD).
298	                out.append(Replacement);
299	            } else if (c <= '\u001F' || c == '\u007F') {
300	                // If the character is in the range [\1-\1f] (U+0001 to U+001F) or is U+007F, then the character
301	                // escaped as code point.
302	                appendEscapedCodepoint(out, c);
303	            } else if (isIdent(c)) {
304	                // If the character is not handled by one of the above rules and is greater than or equal to U+0080,
305	                // is "-" (U+002D) or "_" (U+005F), or is in one of the ranges [0-9] (U+0030 to U+0039),
306	                // [A-Z] (U+0041 to U+005A), or [a-z] (U+0061 to U+007A), then the character itself.
307	                out.append(c);
308	            } else {
309	                // Otherwise, the escaped character.
310	                appendEscaped(out, c);
311	            }
312	        }
313	
314	        q.close();
315	        return StringUtil.releaseBuilder(out);
316	    }
317	
318	    private static void appendEscaped(StringBuilder out, char c) {
319	        out.append(Esc).append(c);
320	    }
321	
322	    private static void appendEscapedCodepoint(StringBuilder out, char c) {
323	        out.append(Esc).append(Integer.toHexString(c)).append(' ');
324	    }
325	
326	    /**
327	     * Pulls the next run of whitespace characters of the queue.
328	     * @return Whether consuming whitespace or not
329	     */
330	    public boolean consumeWhitespace() {
331	        boolean seen = false;
332	        while (matchesWhitespace()) {
333	            advance();
334	            seen = true;
335	        }
336	        return seen;
337	    }
338	
339	    /**
340	     * Consume a CSS element selector (tag name, but | instead of : for namespaces (or *| for wildcard namespace), to not conflict with :pseudo selects).
341	     * 
342	     * @return tag name
343	     */
344	    public String consumeElementSelector() {
345	        return consumeEscapedCssIdentifier(ElementSelectorChars);
346	    }
347	    private static final char[] ElementSelectorChars = {'*', '|', '_', '-'};
348	
349	    /**
350	     Consume a CSS identifier (ID or class) off the queue.
351	     <p>Note: For backwards compatibility this method supports improperly formatted CSS identifiers, e.g. {@code 1} instead
352	     of {@code \31}.</p>
353	
354	     @return The unescaped identifier.
355	     @throws IllegalArgumentException if an invalid escape sequence was found. Afterward, the state of the TokenQueue
356	     is undefined.
357	     @see <a href="https://www.w3.org/TR/css-syntax-3/#consume-name">CSS Syntax Module Level 3, Consume an ident sequence</a>
358	     @see <a href="https://www.w3.org/TR/css-syntax-3/#typedef-ident-token">CSS Syntax Module Level 3, ident-token</a>
359	     */
360	    public String consumeCssIdentifier() {
361	        if (isEmpty()) throw new IllegalArgumentException("CSS identifier expected, but end of input found");
362	
363	        // Fast path for CSS identifiers that don't contain escape sequences.
364	        String identifier = reader.consumeMatching(TokenQueue::isIdent);
365	        char c = current();
366	        if (c != Esc && c != Unicode_Null) {
367	            // If we didn't end on an Esc or a Null, we consumed the whole identifier
368	            return identifier;
369	        }
370	
371	        // An escape sequence was found. Use a StringBuilder to store the decoded CSS identifier.
372	        StringBuilder out = StringUtil.borrowBuilder();
373	        if (!identifier.isEmpty()) {
374	            // Copy the CSS identifier up to the first escape sequence.
375	            out.append(identifier);
376	        }
377	
378	        while (!isEmpty()) {
379	            c = current();
380	            if (isIdent(c)) {
381	                out.append(consume());
382	            } else if (c == Unicode_Null) {
383	                // https://www.w3.org/TR/css-syntax-3/#input-preprocessing
384	                advance();
385	                out.append(Replacement);
386	            } else if (c == Esc) {
387	                advance();
388	                if (!isEmpty() && isNewline(current())) {
389	                    // Not a valid escape sequence. This is treated as the end of the CSS identifier.
390	                    reader.unconsume();
391	                    break;
392	                } else {
393	                    consumeCssEscapeSequenceInto(out);
394	                }
395	            } else {
396	                break;
397	            }
398	        }
399	        return StringUtil.releaseBuilder(out);
400	    }
401	
402	    private void consumeCssEscapeSequenceInto(StringBuilder out) {
403	        if (isEmpty()) {
404	            out.append(Replacement);
405	            return;
406	        }
407	
408	        char firstEscaped = consume();
409	        if (!StringUtil.isHexDigit(firstEscaped)) {
410	            out.append(firstEscaped);
411	        } else {
412	            reader.unconsume(); // put back the first hex digit
413	            String hexString = reader.consumeMatching(StringUtil::isHexDigit, 6); // consume up to 6 hex digits
414	            int codePoint;
415	            try {
416	                codePoint = Integer.parseInt(hexString, 16);
417	            } catch (NumberFormatException e) {
418	                throw new IllegalArgumentException("Invalid escape sequence: " + hexString, e);
419	            }
420	            if (isValidCodePoint(codePoint)) {
421	                out.appendCodePoint(codePoint);
422	            } else {
423	                out.append(Replacement);
424	            }
425	
426	            if (!isEmpty()) {
427	                char c = current();
428	                if (c == '\r') {
429	                    // Since there's currently no input preprocessing, check for CRLF here.
430	                    // https://www.w3.org/TR/css-syntax-3/#input-preprocessing
431	                    advance();
432	                    if (!isEmpty() && current() == '\n') advance();
433	                } else if (c == ' ' || c == '\t' || isNewline(c)) {
434	                    advance();
435	                }
436	            }
437	        }
438	    }
439	
440	    // statics below specifically for CSS identifiers:
441	
442	    // https://www.w3.org/TR/css-syntax-3/#non-ascii-code-point
443	    private static boolean isNonAscii(char c) {
444	        return c >= '\u0080';
445	    }
446	
447	    // https://www.w3.org/TR/css-syntax-3/#ident-start-code-point
448	    private static boolean isIdentStart(char c) {
449	        return c == '_' || StringUtil.isAsciiLetter(c) || isNonAscii(c);
450	    }
451	
452	    // https://www.w3.org/TR/css-syntax-3/#ident-code-point
453	    private static boolean isIdent(char c) {
454	        return c == Hyphen_Minus || StringUtil.isDigit(c) || isIdentStart(c);
455	    }
456	
457	    // https://www.w3.org/TR/css-syntax-3/#newline
458	    // Note: currently there's no preprocessing happening.
459	    private static boolean isNewline(char c) {
460	        return c == '\n' || c == '\r' || c == '\f';
461	    }
462	
463	    // https://www.w3.org/TR/css-syntax-3/#consume-an-escaped-code-point
464	    private static boolean isValidCodePoint(int codePoint) {
465	        return codePoint != 0 && Character.isValidCodePoint(codePoint) && !Character.isSurrogate((char) codePoint);
466	    }
467	
468	    private static final char[] CssIdentifierChars = {'-', '_'};
469	
470	    private String consumeEscapedCssIdentifier(char... matches) {
471	        StringBuilder sb = StringUtil.borrowBuilder();
472	        while (!isEmpty()) {
473	            char c = current();
474	            if (c == Esc) {
475	                advance();
476	                if (!isEmpty()) sb.append(consume());
477	                else break;
478	            } else if (matchesCssIdentifier(matches)) {
479	                sb.append(c);
480	                advance();
481	            } else {
482	                break;
483	            }
484	        }
485	        return StringUtil.releaseBuilder(sb);
486	    }
487	
488	    private boolean matchesCssIdentifier(char... matches) {
489	        return matchesWord() || reader.matchesAny(matches);
490	    }
491	
492	    /**
493	     Consume and return whatever is left on the queue.
494	     @return remainder of queue.
495	     */
496	    public String remainder() {
497	        return reader.consumeToEnd();
498	    }
499	
500	    @Override
501	    public String toString() {
502	        return reader.toString();
503	    }
504	
