17	 *
18	 * @author Jonathan Hedley
19	 */
20	public class Collector {
21	
22	    private Collector() {}
23	
24	    /**
25	     Build a list of elements, by visiting the root and every descendant of root, and testing it against the Evaluator.
26	     @param eval Evaluator to test elements against
27	     @param root root of tree to descend
28	     @return list of matches; empty if none
29	     */
30	    public static Elements collect(Evaluator eval, Element root) {
31	        Stream<Element> stream = eval.wantsNodes() ?
32	            streamNodes(eval, root, Element.class) :
33	            stream(eval, root);
34	        Elements els = stream.collect(toCollection(Elements::new));
35	        eval.reset(); // drops any held memos
36	        return els;
37	    }
38	
39	    /**
40	     Obtain a Stream of elements by visiting the root and every descendant of root and testing it against the evaluator.
41	
42	     @param evaluator Evaluator to test elements against
43	     @param root root of tree to descend
44	     @return A {@link Stream} of matches
45	     @since 1.19.1
46	     */
47	    public static Stream<Element> stream(Evaluator evaluator, Element root) {
48	        evaluator.reset();
49	        return root.stream().filter(evaluator.asPredicate(root));
50	    }
51	
52	    /**
53	     Obtain a Stream of nodes, of the specified type, by visiting the root and every descendant of root and testing it
54	     against the evaluator.
55	
56	     @param evaluator Evaluator to test elements against
57	     @param root root of tree to descend
58	     @param type the type of node to collect (e.g. {@link Element}, {@link LeafNode}, {@link TextNode} etc)
59	     @param <T> the type of node to collect
60	     @return A {@link Stream} of matches
61	     @since 1.21.1
62	     */
63	    public static <T extends Node> Stream<T> streamNodes(Evaluator evaluator, Element root, Class<T> type) {
64	        evaluator.reset();
65	        return root.nodeStream(type).filter(evaluator.asNodePredicate(root));
66	    }
