72	     @param root root of tree to descend
73	     @return the first match; {@code null} if none
74	     */
75	    public static @Nullable Element findFirst(Evaluator eval, Element root) {
76	        Element el = stream(eval, root).findFirst().orElse(null);
77	        eval.reset();
78	        return el;
79	    }
80	
81	    /**
82	     Finds the first Node that matches the Evaluator that descends from the root, and stops the query once that first
83	     match is found.
84	
85	     @param eval Evaluator to test elements against
86	     @param root root of tree to descend
87	     @param type the type of node to collect (e.g. {@link Element}, {@link LeafNode}, {@link TextNode} etc)
88	     @return the first match; {@code null} if none
89	     @since 1.21.1
90	     */
91	    public static <T extends Node> @Nullable T findFirstNode(Evaluator eval, Element root, Class<T> type) {
92	        T node = streamNodes(eval, root, type).findFirst().orElse(null);
93	        eval.reset();
94	        return node;
95	    }
96	
97	    /**
98	     Build a list of nodes that match the supplied criteria, by visiting the root and every descendant of root, and
99	     testing it against the Evaluator.
100	
101	     @param evaluator Evaluator to test elements against
102	     @param root root of tree to descend
103	     @param type the type of node to collect (e.g. {@link Element}, {@link LeafNode}, {@link TextNode} etc)
104	     @param <T> the type of node to collect
105	     @return list of matches; empty if none
106	     */
107	    public static <T extends Node> Nodes<T> collectNodes(Evaluator evaluator, Element root, Class<T> type) {
108	        return streamNodes(evaluator, root, type).collect(toCollection(Nodes::new));
109	    }
