import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;
import org.jsoup.select.QueryParser;
import org.jsoup.select.Evaluator;

public class Probe2 {
    static int fails = 0;
    static void check(String label, Object actual, Object expected) {
        boolean ok = String.valueOf(actual).equals(String.valueOf(expected));
        if (!ok) { fails++; System.out.println("FAIL " + label + " => got [" + actual + "] expected [" + expected + "]"); }
        else System.out.println("ok   " + label + " = " + actual);
    }
    static String ids(Document d, String css) { return String.join(",", d.select(css).eachAttr("id")); }
    static void expectThrow(String label, String css) {
        try { Document d = Jsoup.parse("<div id=s><b id=x title='a,b'>1</b><i id=y>2</i><b id=z>3</b></div>");
            d.select(css);
            fails++; System.out.println("FAIL " + label + " expected throw for: " + css);
        } catch (Selector.SelectorParseException e) {
            System.out.println("ok   " + label + " threw");
        }
    }
    public static void main(String[] a) {
        // parsed DOM values: entities decoded in attributes
        Document ent = Jsoup.parse("<div id=s><b id=x title='a&amp;b'>1</b><b id=z title='a&amp;b'>2</b><b id=w>3</b></div>");
        check("entity decoded attr", ids(ent, "#s>:nth-child(2 of b[title='a&b'])"), "z");

        // nested of inside of
        Document nest = Jsoup.parse("<div id=s><b id=x><i></i></b><i id=y></i><b id=z><i></i></b></div>");
        check("nested of-of", ids(nest, "#s>:nth-child(2 of b:has(i))"), "z");

        // :has inside S
        check("has in S", ids(nest, "#s>:nth-child(1 of b:has(i))"), "x");

        // descendant combinator inside S
        Document comb = Jsoup.parse("<div id=s><b id=x><q></q></b><b id=z></b><b id=w><q></q></b></div>");
        check("desc combinator in S", ids(comb, "#s>:nth-child(2 of b:has(q))"), "w");

        // CSS escape: class with comma via escape in S
        Document esc = Jsoup.parse("<div id=s><b id=x class='a,b'>1</b><b id=z class='a,b'>2</b><b id=w class='c'>3</b></div>");
        check("esc comma class", ids(esc, "#s>:nth-child(2 of b.a\\,b)"), "z");
        // hex escape
        check("hex escape class", ids(esc, "#s>:nth-child(2 of b.a\\2c b)"), "z");

        // attribute with quoted comma using double quotes
        Document q2 = Jsoup.parse("<div id=s><b id=x title=\"p,q\">1</b><b id=z title=\"p,q\">2</b></div>");
        check("dquote comma", ids(q2, "#s>:nth-child(2 of b[title=\"p,q\"])"), "z");
        // escaped quote inside quoted attr value
        check("escaped quote", ids(q2, "#s>:nth-child(1 of b[title^='p\\,'])"), "x");

        // n (step only) all
        Document all = Jsoup.parse("<div id=s><b id=x>1</b><i></i><b id=z>2</b><b id=w>3</b></div>");
        check("n of b all", ids(all, "#s>:nth-child(n of b)"), "x,z,w");
        check("-n+3 first3", ids(all, "#s>:nth-child(-n+3 of b)"), "x,z,w");
        check("2n evens", ids(all, "#s>:nth-child(2n of b)"), "z");
        check("2n+1 odds", ids(all, "#s>:nth-child(2n+1 of b)"), "x,w");

        // uppercase keywords
        check("uppercase OF", ids(all, "#s>:NTH-CHILD(2 OF B)"), "z");

        // tabs/newlines as whitespace around of
        check("tabs around of", ids(all, "#s>:nth-child(2\tof\tb)"), "z");

        // ---- error cases ----
        expectThrow("S whitespace only", ":nth-child(2 of   )");
        expectThrow("unclosed square bracket", ":nth-child(2 of b[title)");
        expectThrow("trailing garbage in S", ":nth-child(2 of b !)");
        expectThrow("missing space before of", ":nth-child(2of b)");
        expectThrow("missing space after of", ":nth-child(2 ofb)");
        expectThrow("double of", ":nth-child(2 of b of i)");
        expectThrow("empty parens", ":nth-child()");
        expectThrow("nested empty not", ":nth-child(1 of b:not())");
        expectThrow("S branch trailing combinator", ":nth-child(1 of b ~ )");
        expectThrow("bad pseudo in S", ":nth-child(1 of b:bogus())");
        expectThrow("unclosed quote dbl", ":nth-child(1 of b[title=\"x])");
        expectThrow("illegal escape trailing", ":nth-child(1 of b[title=x\\])");
        expectThrow("odd of bad combo", ":nth-child(odd of b, )");

        // legal-but-no-match branch keeps other branch
        Document mix = Jsoup.parse("<div id=s><b id=x>1</b><i id=y>2</i><b id=z>3</b></div>");
        check("nomatch+match", ids(mix, "#s>:nth-child(99 of b), #s>i"), "y");
        check("match+nomatch", ids(mix, "#s>i, #s>:nth-child(99 of b)"), "y");

        // toString roundtrip of evaluator
        Evaluator ev = QueryParser.parse(":nth-child(2 of b, i)");
        System.out.println("   toString = " + ev);
        check("toString reparses", ids(all, ev.toString()), "z");

        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
    }
}
