    static String[] cls = {"", "x", "a", "x"};

    static boolean nth(int a, int b, int pos) {
        if (a == 0) return pos == b;
        return (pos - b) * a >= 0 && (pos - b) % a == 0;
    }

    public static void main(String[] z) {
        String[] forms = {
            "1","2","3","0","-1","odd","even","n","2n","2n+1","3n","-n+2","-2n+3","n+1","0n+1","-n+5","5n-2"
        };
        String[] ofs = {"b","i","b.x",".a","b:not(.x)","[title]","b, i","b.a, i","*","b:nth-child(odd)","em, b.x"};
        for (int iter = 0; iter < 4000; iter++) {
