            StringBuilder h = new StringBuilder("<div id=s>");
            for (int i=0;i<n;i++){
                String t = tags[rnd.nextInt(tags.length)];
                String c = cls[rnd.nextInt(cls.length)];
                String ti = rnd.nextBoolean() ? " title=t" : "";
                h.append("<").append(t).append(" id=c").append(i)
                 .append(c.isEmpty()?"":" class="+c).append(ti).append("></"+t+">");
