            h.append("</div>");
            Document doc = Jsoup.parse(h.toString());
            Element s = doc.getElementById("s");
            List<Element> kids = s.children();

            String form = forms[rnd.nextInt(forms.length)];
            String of = ofs[rnd.nextInt(ofs.length)];
            boolean last = rnd.nextBoolean();
            String css = "#s>:nth"+(last?"-last":"")+"-child("+form+" of "+of+")";

            // parse a,b
            int a,b;
            switch(form){
                case "odd": a=2;b=1;break;
                case "even": a=2;b=0;break;
                default:
                    if(form.contains("n")){
                        String[] p = form.split("n");
                        String st = p[0];
                        if(st.isEmpty())a=1; else if(st.equals("-"))a=-1; else if(st.equals("+"))a=1; else a=Integer.parseInt(st);
                        b = p.length>1 && !p[1].isEmpty()? Integer.parseInt(p[1].replace("+","")) : 0;
                    } else { a=0; b=Integer.parseInt(form); }
