            for (Element k : kids) {
                if (!S.matches(doc, k)) continue;
                int pos;
                if (last) pos = cands.size() - cands.indexOf(k);
                else pos = cands.indexOf(k) + 1;
                if (nth(a,b,pos)) refFwd.add(k);
            }

            List<Element> got = doc.select(css);
            List<String> refIds = new ArrayList<>(); for (Element e: refFwd) refIds.add(e.id());
            List<String> gotIds = new ArrayList<>(); for (Element e: got) gotIds.add(e.id());
            if (!refIds.equals(gotIds)) {
                fails++;
                if (fails <= 15) System.out.println("MISMATCH css="+css+"\n  html="+h+"\n  ref="+refIds+"\n  got="+gotIds);
            }
        }
        System.out.println(fails==0?"DIFF ALL PASS":(fails+" mismatches"));
    }
}
