    public static void main(String[] a){
        Document xml=Parser.xmlParser().parseInput("<r><B id='x'/><b id='y'/><B id='z'/></r>","");
        System.out.println("plain B -> "+String.join(",",xml.select("B").eachAttr("id")));
        System.out.println("plain b -> "+String.join(",",xml.select("b").eachAttr("id")));
        System.out.println("B:nth-child(3) -> "+String.join(",",xml.select("B:nth-child(3)").eachAttr("id")));
        System.out.println("b:nth-child(2) -> "+String.join(",",xml.select("b:nth-child(2)").eachAttr("id")));
        System.out.println(":nth-of-type via B -> "+String.join(",",xml.select("B:nth-of-type(2)").eachAttr("id")));
        System.out.println("of B -> "+String.join(",",xml.select(":nth-child(2 of B)").eachAttr("id")));
        System.out.println("of b -> "+String.join(",",xml.select(":nth-child(1 of b)").eachAttr("id")));
        System.out.println(":is(B) -> "+String.join(",",xml.select(":is(B)").eachAttr("id")));
        System.out.println(":not(B) -> "+String.join(",",xml.select("r > *:not(B)").eachAttr("id")));
    }
}
