import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;
import java.util.List;
import java.util.stream.Collectors;

public class Final {
    static int fails=0;
    static void check(String l,Object a,Object e){boolean ok=String.valueOf(a).equals(String.valueOf(e));
        if(!ok){fails++;System.out.println("FAIL "+l+"\n  got ["+a+"]\n  exp ["+e+"]");}else System.out.println("ok "+l);}
    public static void main(String[] x){
        // (3) same instance: capture results, trigger failure, re-run -> identical
        Document d=Jsoup.parse("<div id=s><b id=x class='a b'>1</b><i id=y>2</i><b id=z class='b a'>3</b></div>");
        List<String> tagBefore=d.select("b").eachAttr("id");
        List<String> attrBefore=d.select("[id]").eachAttr("id");
        List<String> structBefore=d.select("#s > i").eachAttr("id");
        List<String> multiBefore=d.select("b.a.b").eachAttr("id"); // multi-class tokenization
        boolean threw=false;
        try { d.select(":nth-child(2 of b > )"); } catch (Selector.SelectorParseException e){ threw=true; }
        check("failure threw", threw, true);
        check("tag same after fail", d.select("b").eachAttr("id"), tagBefore);
        check("attr same after fail", d.select("[id]").eachAttr("id"), attrBefore);
        check("struct same after fail", d.select("#s > i").eachAttr("id"), structBefore);
        check("multi-class tokenized in S", d.select(":nth-child(2 of b.a.b)").eachAttr("id"), "z");
        check("multi-class before==after", d.select("b.a.b").eachAttr("id"), multiBefore);

        // (4) strong round-trip: outerHtml + hierarchy path + order + dedup
        Document rt=Jsoup.parse(
            "<div id=p><b id=x>1</b><i id=y>2</i><b id=z>3</b><i id=q>4</i></div>");
        String css=":nth-child(2 of b, i), b";
        List<String> sig(Document doc){
            return doc.select(css).stream().map(e ->
                e.tagName()+"|"+e.ownText()+"|"+e.parent().tagName()+"#"+e.parent().id()+"|"+e.elementSiblingIndex()
                +"|"+e.outerHtml()).collect(Collectors.toList());
        }
        Document rp=Jsoup.parse(rt.html());
        check("roundtrip sig", sig(rp), sig(rt));
        // dedup: b appears in both branches but once
        check("dedup count", rt.select(css).size(), rt.select(css).stream().distinct().count());
        // order is document order
        List<String> ids=rt.select(css).eachAttr("id");
        check("doc order", ids, java.util.Arrays.asList("x","y","z","q"));

        // contains in S based on parsed text
        Document ct=Jsoup.parse("<div id=s><b id=x>a &amp; b</b><b id=z>a &amp; b</b><b id=w>c</b></div>");
        check("contains entity text", ct.select("#s>:nth-child(2 of b:contains(a & b))").eachAttr("id"), "z");

        System.out.println(fails==0?"ALL PASS":fails+" FAIL");
    }
}
