import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import java.util.*;
public class Parity {
    static int fails=0;
    static Random r=new Random(99);
    public static void main(String[] a){
        String[] forms={"1","2","3","4","0","-1","-3","+2","odd","even","n","2n","3n","-n","-2n","n+1","n+2","n-1",
            "2n+1","2n-1","-n+1","-n+2","-2n+3","-3n+5","0n+1","0n+2","+n","+2n","5n-2","-n+10"};
        for(int it=0;it<6000;it++){
            int n=1+r.nextInt(9);
            StringBuilder h=new StringBuilder("<div id=s>");
            for(int i=0;i<n;i++) h.append("<b id=e").append(i).append(">").append(i).append("</b>");
            h.append("</div>");
            Document d=Jsoup.parse(h.toString());
            String f=forms[r.nextInt(forms.length)];
            boolean last=r.nextBoolean();
            String pc=":nth"+(last?"-last":"")+"-child";
            String plain, of;
            try {
                plain=String.join(",",d.select("#s>b"+pc+"("+f+")").eachAttr("id"));
            } catch(Exception e){ plain="THROW"; }
            try {
                of=String.join(",",d.select("#s>b"+pc+"("+f+" of *)").eachAttr("id"));
            } catch(Exception e){ of="THROW"; }
            if(!plain.equals(of)){
                fails++;
                if(fails<=15) System.out.println("PARITY FAIL "+pc+"("+f+") plain=["+plain+"] of*=["+of+"] n="+n);
            }
        }
        System.out.println(fails==0?"PARITY ALL PASS":fails+" parity fails");
    }
}
