import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;
public class Last {
    static int fails=0;
    static void ck(String l,Object a,Object e){boolean ok=String.valueOf(a).equals(String.valueOf(e));
        if(!ok){fails++;System.out.println("FAIL "+l+" got["+a+"] exp["+e+"]");}else System.out.println("ok "+l+"="+a);}
    static String ids(Document d,String c){return String.join(",",d.select(c).eachAttr("id"));}
    static void thr(String l,String c){try{Jsoup.parse("<div><of id=q></of><b id=x></b></div>").select(c);
        fails++;System.out.println("FAIL "+l+" no throw");}catch(Selector.SelectorParseException e){System.out.println("ok "+l+" threw");}}
    public static void main(String[] a){
        Document d=Jsoup.parse("<div id=s><of id=o1></of><b id=x></b><of id=o2></of></div>");
        ck("of as tag 2nd", ids(d,"#s>:nth-child(2 of of)"), "o2");
        ck("of tag 1st", ids(d,"#s>:nth-child(1 of of)"), "o1");

        Document d2=Jsoup.parse("<div id=s><b id=x class='a'></b><i id=y></i><b id=z class='b'></b><em id=w></em></div>");
        ck("deep paren in S", ids(d2,"#s>:nth-child(3 of b:is(.a, .b), i, em)"), "w");
        ck("nested functional", ids(d2,"#s>:nth-child(2 of b:is(:nth-child(1), .b))"), "z");

        // formula with 'n' then of where no space around n but space around of
        ck("n tight", ids(d2,"#s>:nth-child(n of b)"), "x,z");
        // attribute value with parens and commas
        Document d3=Jsoup.parse("<div id=s><b id=x data-v='f(a,b)'></b><b id=z data-v='f(a,b)'></b></div>");
        ck("parens in quoted val", ids(d3,"#s>:nth-child(2 of b[data-v='f(a,b)'])"), "z");
        // unclosed paren inside quoted value should still fail (quote closes, paren unbalanced)
        thr("unbal paren quoted", ":nth-child(2 of b[data-v='f(a,b'])");
        // :not with nested combinator in S
        Document d4=Jsoup.parse("<div id=s><b id=x><q></q></b><b id=y></b><b id=z></b></div>");
        ck("not has", ids(d4,"#s>:nth-child(2 of b:not(:has(q)))"), "z");
        System.out.println(fails==0?"ALL PASS":fails+" FAIL");
    }
}
